package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="rr_fulfillment_event") public class RrFulfillmentEvent extends RspAuditedEntity{public enum Status{PARTIALLY_FULFILLED,FULFILLED,CANCELLED}@Column(name="authorization_id",nullable=false,length=36)private String authorizationId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Status status;@Column(name="fulfilled_amount",precision=19,scale=2)private BigDecimal fulfilledAmount;@Column(nullable=false,length=3000)private String details;@Column(name="evidence_reference",length=500)private String evidenceReference;@Column(name="evidence_checksum",length=64)private String evidenceChecksum;@Column(name="recorded_by",nullable=false,length=100)private String recordedBy;@Column(name="recorded_at",nullable=false)private Instant recordedAt;protected RrFulfillmentEvent(){}public RrFulfillmentEvent(String a,String authorization,Status status,BigDecimal amount,String details,String evidence,String checksum,String actor,Instant at){super(a);authorizationId=requiredText(authorization,"authorizationId");this.status=java.util.Objects.requireNonNull(status,"status");fulfilledAmount=amount==null?null:amount.setScale(2,java.math.RoundingMode.HALF_UP);if(fulfilledAmount!=null&&fulfilledAmount.signum()<=0)throw new IllegalArgumentException("fulfilledAmount must be positive");this.details=requiredText(details,"details");evidenceReference=optionalText(evidence);evidenceChecksum=optionalText(checksum);if(status!=Status.CANCELLED&&(evidenceReference==null||evidenceChecksum==null||!evidenceChecksum.matches("[0-9a-fA-F]{64}")))throw new IllegalArgumentException("Fulfillment evidence reference and SHA-256 checksum are required");recordedBy=requiredText(actor,"actor");recordedAt=java.util.Objects.requireNonNull(at,"recordedAt");}public String getAuthorizationId(){return authorizationId;}public Status getStatus(){return status;}public BigDecimal getFulfilledAmount(){return fulfilledAmount;}public String getDetails(){return details;}public String getEvidenceReference(){return evidenceReference;}public String getEvidenceChecksum(){return evidenceChecksum;}public String getRecordedBy(){return recordedBy;}public Instant getRecordedAt(){return recordedAt;}}
